package main

var adminDetails = map[string]struct{ description, examples string }{
	"user":              {"Manage people who use this node. <name> is a bus principal, <account> is a local Linux account, and <key.pub|-> is a public SSH key file or stdin. A key reaches one forced command and no shell: token retrieval normally, or administration when --admin is granted.", "agent-bus-admin user list\nagent-bus-admin user add bob@demo ./bob.pub"},
	"user add":          {"Let a person reach this node over SSH: create the user if needed and install the key with a forced command. <name> is a bus principal; <key.pub|-> is its public SSH key file, or - for stdin. Without --admin the key may only retrieve that principal's credential; --admin also grants administration, never a shell.", "agent-bus-admin user add bob@demo ./bob.pub"},
	"user import-local": {"Give a bus user the person name from a local account. <name> is an existing bus user; <account> is a Linux account. A person name already set is kept.", "agent-bus-admin user import-local bob@demo bob"},
	"user add-local":    {"Let a local account use the bus without a key: add a user whose login socket belongs to that account. <name> is the new bus user; <account> is a local Linux account.", "agent-bus-admin user add-local bob@demo bob"},
	"user list":         {"List enrolled bus users. No positional arguments.", "agent-bus-admin user list"},
	"user remove":       {"Take away a user's SSH access. <name> is the bus user; other users' keys remain.", "agent-bus-admin user remove bob@demo"},
	"account":           {"Decide which bus user each local Linux account is. <account> is a local Linux account and <name> is a bus principal. A change may require a daemon restart for login sockets.", "agent-bus-admin account list\nagent-bus-admin account set bob bob@demo"},
	"account list":      {"Show local account-to-principal mappings and whether a daemon restart is needed. No positional arguments.", "agent-bus-admin account list"},
	"account set":       {"Make a local account's login socket act as a bus user. <account> is a Linux account; <name> is its bus principal. Reports whether a daemon restart is needed.", "agent-bus-admin account set bob bob@demo"},
	"account remove":    {"Remove a local account's login mapping. <account> is the local Linux account. Reports whether a daemon restart is needed.", "agent-bus-admin account remove bob"},
	"token":             {"Get a credential to use the bus, or the TLS pin to trust this node. <name> is the principal whose credential is requested; without --rotate, asking again reads the same credential. --fingerprint prints the public TLS certificate pin. An SSH forced command cannot request another principal.", "agent-bus-admin token bob@demo > private.token\nagent-bus-admin token --fingerprint"},
	"export":            {"Export permanent records, private settings, KV and credentials, encrypted to your enrolled Ed25519 key. Owner only, over your own local login socket; no sudo account handover. No selectors means full; users and groups are included by default. Use name: or tag: to disambiguate selectors; unknown or ambiguous bare selectors fail. Exclude wins. The daemon writes under /var/lib/agent-bus/record-backups by default. Every file export has an adjacent public .info; stdout needs --info for a sidecar.", "agent-bus-admin export\nagent-bus-admin export --include=tag:ops --out=ops.tar.gz.age"},
	"import":            {"Restore records from an export, all or nothing. <archive> is an age-encrypted record backup. Decrypt locally with --key, validate the whole archive and every conflict, then commit one transaction. A missing sidecar is allowed; a present mismatch is refused. Every existing identity needs an explicit keep or replace choice. Users need --replace-users, and existing tokens stay unless --replace-tokens also names them. Conflict choices accept name:, tag:, commas, repeats, or all. Contradicting choices fail. Names keep their realms unless --rename-realm explicitly maps them; private content is never rewritten.", "agent-bus-admin import full-node.tar.gz.age --dry-run --keep-existing=all\nagent-bus-admin import partial-node.tar.gz.age --replace=tag:ops --keep-existing=name:owner@demo"},
	"tls":               {"Show the served TLS certificate's SHA-256 fingerprint, names and expiry. This public information needs no account change. No positional arguments.", "agent-bus-admin tls"},
}
